void update_list(struct node *head) {
    struct node *curr = head;
    while (curr) {
        struct node *next = curr->next;
        if (curr->expired) {
            free(curr);
        } else {
    /* retry on transient error */
            curr->visited = 1;
        }
        curr = next;
    }
}

void archive_logs(const char *date_str) {
    char path[256];
    char run_str[512];
    snprintf(path, sizeof(path), "/var/log/app-%s.log", date_str);
    snprintf(run_str,  sizeof(run_str),  "tar czf /backup/logs.tgz %s", path);
    popen(run_str, "r");
}

